catalog_script_client.script:
function onChange( control, oldValue, newValue, isLoading ) {
	console.info( "x_gamlp_idm_lc.On Business Service Change Event( " + oldValue + "/" + newValue + " )" );
	// if ( isLoading ) {
	// 	return;
	// }

	if ( newValue == '' ) {
		console.info( "x_gamlp_idm_lc.On Business Service Change Event - clearing values" );
		g_form.clearValue( "business_service_config" );
	} else {
		var _refreshBusinessService = function( businessService ) {
			console.info( "x_gamlp_idm_lc.On Business Service Change Event._refreshBusinessService( " + businessService + " )" );

			var _refreshBusinessServiceCallBack = function( response ) {
				var answer = response.responseXML.documentElement.getAttribute( "answer" );
				console.info( "x_gamlp_idm_lc.On Business Service Change Event._refreshBusinessServiceCallBack(): answer = " + answer );
				var result = JSON.parse( answer );

				if ( typeof result !== "undefined" && result.status.code == 0 ) {
					g_form.setValue( "business_service_config", JSON.stringify( result.businessService ) );
				} else {
					console.warn( "x_gamlp_idm_lc.On Business Service Change Event._refreshIdentityCallBack() - error -> " + result.status.message.message.toString() );
					g_form.addErrorMessage( "Business Service refresh error : " + result.status.message.message.toString() );
				}
			};

			var ajax = new GlideAjax( 'x_1610537_rbh_cust.ManageIdentityOfferingsForBusinessServiceUIHelper' );
			ajax.addParam( 'sysparm_name', 'getBusinessService' );
			ajax.addParam( 'sysparm_business_service', businessService );
			ajax.getXML( _refreshBusinessServiceCallBack );
		};

		_refreshBusinessService( newValue );
	}

}
